# Generated by build.py from recipe.yml for recipe mqtt-subscribe-with-a-wildcard. Do not edit.
set -e
cd "$(dirname "$0")"
surl --allow-anonymous --topic "sensors/#;retain" mqtt://127.0.0.1:8080/ &
sleep 1
curl -s -d 21 mqtt://127.0.0.1:8080/sensors/kitchen/temp
curl -s -d 19 mqtt://127.0.0.1:8080/sensors/hall/temp
curl -s -d 40 mqtt://127.0.0.1:8080/sensors/kitchen/humidity
curl -s -d 180 mqtt://127.0.0.1:8080/sensors/kitchen/oven/temp
curl -s -d 5 mqtt://127.0.0.1:8080/sensors/temp
curl -s -d up mqtt://127.0.0.1:8080/sensors
curl -s mqtt://127.0.0.1:8080/sensors/+/temp
kill $(jobs -p)
